replacements.new:
function bool HandleSpellFlipendo (optional baseSpell spell, optional Vector vHitLocation)
{
	local HPCoopGame CoopGame;
	local harry PushSource, CoopCaster;

	Super.HandleSpellFlipendo(spell,vHitLocation);
	if ( bFlipPushable == True )
	{
		// Preserve the original actor context; only this shove uses its caster.
		PushSource = PlayerHarry;
		CoopGame = HPCoopGame(Level.Game);
		if ( Role == ROLE_Authority && Level.NetMode != NM_Client
			&& CoopGame != None && spell != None && !spell.bDeleteMe )
		{
			CoopCaster = harry(spell.Instigator);
			if ( CoopCaster == None || CoopCaster.bDeleteMe
				|| !CoopGame.IsCoopPlayer(CoopCaster) )
				CoopCaster = harry(spell.Owner);
			if ( CoopCaster != None && !CoopCaster.bDeleteMe
				&& CoopGame.IsCoopPlayer(CoopCaster) )
				PushSource = CoopCaster;
		}
		SetPhysics(PHYS_Falling);
		Velocity = Normal(Location - PushSource.Location) * fFlipPushForceXY;
		Velocity.Z = fFlipPushForceZ;
	}
	return True;
}
